actions.script:
const out = ec.service.sync().name('ironstone.projects.TimeImportServices.get#ImportDraft').parameters({importId: importId}).call()
if (!out?.folder || !out.found) { ec.message.addError(ec.l10n.localize('This import is not available; start again from the file')); return }
draft = Object.assign({}, out.draft || {}, fields || {}, {importId: importId, updated: Number(String(ec.user.nowTimestamp))})
ec.resource.getLocationReference(out.folder + '/draft.json').putText(JSON.stringify(draft))

const L = (text) => ec.l10n.localize(text)
const userId = ec.user.userId
if (!userId) { ec.message.addError(L('An import needs a user')); return }
const me = ec.user.userAccount?.partyId || null
const person = partyId || me
if (person !== me) {
    const people = Array.from(ec.service.sync().name('ironstone.projects.TimeServices.get#TimePeople').call()?.personOptions || []).map((option) => option.key)
    if (!people.includes(person)) { ec.message.addValidationError(null, 'partyId', null, L('You may not log time for that person'), null); return }
}
let current = importId ? ec.service.sync().name('ironstone.projects.TimeImportServices.get#ImportDraft').parameters({importId: importId}).call() : null
if (!current?.found) {
    importId = String(Number(String(ec.user.nowTimestamp))) + '-' + Math.floor(Math.random() * 1e6)
    current = null
}
const hasUpload = timeEntryFile != null && Number(timeEntryFile.size || 0) > 0
if (!hasUpload && !current?.fileLocation) { ec.message.addValidationError(null, 'timeEntryFile', null, L('Choose a CSV file'), null); return }
const folder = `dbresource://ironstone/TimeImport/${userId}/${importId}`
let fileName = current?.draft?.fileName || null
const charset = String(characterSet || 'UTF-8').toUpperCase()
if (hasUpload) {
    fileName = String(timeEntryFile.getName ? timeEntryFile.getName() : timeEntryFile.name || 'time-entries.csv')
    const read = ec.service.sync().name('mantle.party.ContactImportServices.read#ContactFileText').parameters({contactFile: timeEntryFile,
        characterSet: charset}).call()
    if (ec.message.hasError()) return
    ec.resource.getLocationReference(`${folder}/source.csv`).putText(String(read?.text ?? ''))
}
const checked = ec.service.sync().name('mantle.work.TimeServices.import#TimeEntryCsv').parameters({fileLocation: `${folder}/source.csv`,
    partyId: person, preview: true, maxRows: 1}).call()
if (ec.message.hasError()) return
rowCount = checked.rowCount || 0
if (!rowCount) { ec.message.addError(L('The file has no time entries')); return }
ec.resource.getLocationReference(folder + '/draft.json').putText(JSON.stringify(Object.assign({}, current?.draft || {}, {importId: importId,
    fileName: fileName, characterSet: charset, rowCount: rowCount, partyId: person, columnMapping: checked.columnMapping || {},
    unusedColumns: Array.from(checked.unusedColumns || []), result: null, status: 'source', created: current?.draft?.created || Number(String(ec.user.nowTimestamp))})))

preview = null
const L = (text) => ec.l10n.localize(text)
const current = ec.service.sync().name('ironstone.projects.TimeImportServices.get#ImportDraft').parameters({importId: importId}).call() || {}
if (!current.found) return
const draft = current.draft
const out = ec.service.sync().name('mantle.work.TimeServices.import#TimeEntryCsv').parameters({fileLocation: current.fileLocation,
    partyId: draft.partyId || null, preview: true, maxRows: 50}).call()
if (ec.message.hasError()) { preview = {error: ec.message.getErrorsString(), rowList: []}; ec.message.clearErrors(); return }
const n = (value) => value == null ? '' : ec.l10n.format(value, '#,##0.##')
const actions = {create: L('Create'), skip: L('Skip'), fail: L('Fails')}
const styles = {create: 'text-positive', skip: 'm-muted', fail: 'text-negative'}
const counts = out.counts || {}
const mapping = out.columnMapping || {}
const targets = {date: 'date', person: 'person', item: 'work item', project: 'project', hours: 'hours', start: 'start', end: 'end',
    workType: 'work type', billable: 'billable', comment: 'comment'}
preview = {draft: draft, rowList: Array.from(out.previewList || []).map((row) => ({rowNumber: row.rowNumber, day: row.day, personName: row.personName,
        itemText: row.workEffortId ? row.workEffortId + ' ' + row.itemName : '', projectName: row.projectName, hoursText: n(row.hours),
        spanText: row.fromText ? row.fromText + '–' + row.thruText : '', workTypeLabel: row.workTypeLabel, billableText: row.billable ? L('Billable') : L('Not billable'),
        comments: row.comments, actionLabel: actions[row.action] || row.action, actionStyle: styles[row.action] || '',
        problemText: Array.from(row.problems || []).concat(Array.from(row.warnings || [])).join('; '), problemStyle: (row.problems || []).length ? 'text-negative' : 'text-warning'})),
    summaryText: ec.resource.expand('${rows} rows: ${create} to create, ${skip} to skip (logged already), ${fail} failing, ${warned} with warnings', '',
        {rows: counts.rows || 0, create: counts.create || 0, skip: counts.skip || 0, fail: counts.fail || 0, warned: counts.warned || 0}),
    mappingText: Object.entries(mapping).map(([target, column]) => (targets[target] || target) + ' ← ' + column).join(', '),
    unusedText: Array.from(out.unusedColumns || []).join(', '), moreRows: Number(counts.rows || 0) > 50, createCount: counts.create || 0}

const L = (text) => ec.l10n.localize(text)
running = false
const current = ec.service.sync().name('ironstone.projects.TimeImportServices.get#ImportDraft').parameters({importId: importId}).call()
if (!current?.found) { ec.message.addError(L('This import is not available; start again from the file')); return }
const draft = current.draft
if (draft.status === 'done') { result = draft.result; return }
if (draft.status === 'running') { running = true; return }
const inBackground = background != null ? !!background : Number(draft.rowCount || 0) > 200
if (!inBackground) {
    result = ec.service.sync().name('ironstone.projects.TimeImportServices.run#ImportNow').parameters({importId: importId}).call()?.result || null
    return
}
ec.service.sync().name('ironstone.projects.TimeImportServices.store#ImportDraft').parameters({importId: importId, fields: {status: 'running',
    error: null, started: Number(String(ec.user.nowTimestamp))}}).call()
if (ec.message.hasError()) return
ec.service.async().name('ironstone.projects.TimeImportServices.run#ImportNow').parameters({importId: importId}).call()
running = true

const L = (text) => ec.l10n.localize(text)
const current = ec.service.sync().name('ironstone.projects.TimeImportServices.get#ImportDraft').parameters({importId: importId}).call()
if (!current?.found) { ec.message.addError(L('This import is not available; start again from the file')); return }
const draft = current.draft
if (draft.status === 'done') { result = draft.result; return }
const fail = (error) => {
    ec.logger.warn(`Time import ${importId} of ${ec.user.userId} stopped: ${error}`)
    ec.service.sync().name('ironstone.projects.TimeImportServices.store#ImportDraft').parameters({importId: importId, fields: {status: 'failed',
        error: error, finished: Number(String(ec.user.nowTimestamp))}}).ignorePreviousError(true).requireNewTransaction(true).call()
}
let out = null
try {
    out = ec.service.sync().name('mantle.work.TimeServices.import#TimeEntryCsv').parameters({fileLocation: current.fileLocation,
        partyId: draft.partyId || null, progressUserId: ec.user.userId, progressKey: importId}).call()
} catch (err) {
    fail(String(err && err.message ? err.message : err)); throw err
}
if (ec.message.hasError()) { fail(ec.message.getErrorsString()); return }
result = {rowCount: out.rowCount || 0, createdCount: out.createdCount || 0, skippedCount: out.skippedCount || 0, failedCount: out.failedCount || 0,
    hoursImported: out.hoursImported ?? 0, failureList: Array.from(out.failureList || []), warningList: Array.from(out.warningList || []).slice(0, 500),
    resultList: Array.from(out.resultList || []).slice(0, 2000)}
ec.service.sync().name('ironstone.projects.TimeImportServices.store#ImportDraft').parameters({importId: importId, fields: {status: 'done', result: result,
    error: null, finished: Number(String(ec.user.nowTimestamp))}}).call()
